from itertools import permutations
class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        extras, holes = [], []
        for i in range(3):
            for j in range(3):
                if grid[i][j] > 1:
                    extras += [(i, j)] * (grid[i][j] - 1)
                elif grid[i][j] == 0:
                    holes.append((i, j))
        if not holes:
            return 0
        best = float('inf')
        for pm in permutations(extras):
            best = min(best, sum(abs(a - c) + abs(b - d)
                                 for (a, b), (c, d) in zip(pm, holes)))
        return best

