class Solution {
public:
    int minimumMoves(vector<vector<int>>& grid) {
        vector<pair<int,int>> ex, ho;
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] > 1)
                    for (int t = 0; t < grid[i][j] - 1; t++) ex.push_back({i, j});
                else if (grid[i][j] == 0) ho.push_back({i, j});
            }
        if (ho.empty()) return 0;
        sort(ex.begin(), ex.end());
        int best = INT_MAX;
        do {
            int c = 0;
            for (int i = 0; i < (int)ho.size(); i++)
                c += abs(ex[i].first - ho[i].first) + abs(ex[i].second - ho[i].second);
            best = min(best, c);
        } while (next_permutation(ex.begin(), ex.end()));
        return best;
    }
};

