class Solution {
    public int minimumMoves(int[][] grid) {
        List<int[]> ex = new ArrayList<>(), ho = new ArrayList<>();
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] > 1)
                    for (int t = 0; t < grid[i][j] - 1; t++) ex.add(new int[]{i, j});
                else if (grid[i][j] == 0) ho.add(new int[]{i, j});
            }
        if (ho.isEmpty()) return 0;
        int[] best = {Integer.MAX_VALUE};
        perm(ex, 0, ho, best);
        return best[0];
    }
    private void perm(List<int[]> ex, int idx, List<int[]> ho, int[] best) {
        if (idx == ex.size()) {
            int c = 0;
            for (int i = 0; i < ho.size(); i++)
                c += Math.abs(ex.get(i)[0] - ho.get(i)[0]) + Math.abs(ex.get(i)[1] - ho.get(i)[1]);
            best[0] = Math.min(best[0], c);
            return;
        }
        for (int i = idx; i < ex.size(); i++) {
            java.util.Collections.swap(ex, idx, i);
            perm(ex, idx + 1, ho, best);
            java.util.Collections.swap(ex, idx, i);
        }
    }
}

