var minimumMoves = function(grid) {
    const ex = [], ho = [];
    for (let i = 0; i < 3; i++)
        for (let j = 0; j < 3; j++) {
            if (grid[i][j] > 1)
                for (let t = 0; t < grid[i][j] - 1; t++) ex.push([i, j]);
            else if (grid[i][j] === 0) ho.push([i, j]);
        }
    if (!ho.length) return 0;
    let best = Infinity;
    const permute = (arr, l) => {
        if (l === arr.length) {
            let c = 0;
            for (let i = 0; i < ho.length; i++)
                c += Math.abs(arr[i][0] - ho[i][0]) + Math.abs(arr[i][1] - ho[i][1]);
            best = Math.min(best, c);
            return;
        }
        for (let i = l; i < arr.length; i++) {
            [arr[l], arr[i]] = [arr[i], arr[l]];
            permute(arr, l + 1);
            [arr[l], arr[i]] = [arr[i], arr[l]];
        }
    };
    permute(ex, 0);
    return best;
};

