class Solution:
    def minimumMoves(self, grid: List[List[int]]) -> int:
        extras, holes = [], []
        for i in range(3):
            for j in range(3):
                if grid[i][j] > 1:
                    extras += [(i, j)] * (grid[i][j] - 1)
                elif grid[i][j] == 0:
                    holes.append((i, j))
        h = len(holes)
        INF = float('inf')
        dp = [INF] * (1 << h)
        dp[0] = 0
        for mask in range(1 << h):
            if dp[mask] == INF:
                continue
            i = bin(mask).count('1')
            for b in range(h):
                if not mask >> b & 1:
                    d = abs(extras[i][0] - holes[b][0]) + abs(extras[i][1] - holes[b][1])
                    dp[mask | 1 << b] = min(dp[mask | 1 << b], dp[mask] + d)
        return dp[(1 << h) - 1]

