public:
    int minimumMoves(vector<vector<int>>& grid) {
        vector<pair<int,int>> ex, ho;
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] > 1)
                    for (int t = 0; t < grid[i][j] - 1; t++) ex.push_back({i, j});
                else if (grid[i][j] == 0) ho.push_back({i, j});
            }
        int h = ho.size(), full = 1 << h;
        vector<int> dp(full, INT_MAX);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] == INT_MAX) continue;
            int i = __builtin_popcount(mask);
            for (int b = 0; b < h; b++)
                if (!(mask >> b & 1)) {
                    int d = abs(ex[i].first - ho[b].first) + abs(ex[i].second - ho[b].second);
                    dp[mask | 1 << b] = min(dp[mask | 1 << b], dp[mask] + d);
                }
        }
        return dp[full - 1];
    }
};

