                else if (grid[i][j] == 0) ho.add(new int[]{i, j});
            }
        int h = ho.size(), full = 1 << h;
        int[] dp = new int[full];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            if (dp[mask] == Integer.MAX_VALUE) continue;
            int i = Integer.bitCount(mask);
            for (int b = 0; b < h; b++)
                if ((mask >> b & 1) == 0) {
                    int d = Math.abs(ex.get(i)[0] - ho.get(b)[0]) + Math.abs(ex.get(i)[1] - ho.get(b)[1]);
                    int nm = mask | 1 << b;
                    dp[nm] = Math.min(dp[nm], dp[mask] + d);
                }
        }
        return dp[full - 1];
    }
